ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["radio_11"] = {
{"r3_sil_d11_company_in_lot","silence",11,30,13,19,1,{"Marty","For those who noticed we were gone most of the afternoon, we had company in the lot - we shut everything off and sat very still, they've moved on","Dee","Twenty-some, it took them two hours to decide the feed store wasn't interesting","Marty","I have never been so glad to be dull"}},
{"r4_sad_recital_tape_floor","caller_story_sad",11,30,19,23,1,{"Caller - Gene","I've got one camcorder tape of my wife, it's the worst tape anybody ever made","Marty","How so?","Caller - Gene","Our granddaughter's piano recital in May, my wife held the camera, she thought she stopped it after the piece - she didn't","Caller - Gene","So it's twenty-two minutes of the carpet in the Rosewood school gym - and her shoes, and her talking","Caller - Gene","Talking to me about the parking, about how the Sutton girl played too fast, about whether I remembered to lock the car","Caller - Gene","I used to tease her about that tape, the carpet movie, I called it, I'd threaten to show it at Christmas","Caller - Gene","I've got the camera hooked to a car battery with an inverter - I watch the carpet for a few minutes at night - I don't let myself have the whole twenty-two","Caller - Gene","Battery's getting low - at minute eleven she says, Gene, did you lock it? I'm saving that part","Dee","(Dee covers the microphone, when she uncovers it, she only says his name)","Dee","Gene"}},
{"r8_hor_sprinkler_dead_lawn","caller_story_horror",11,140,21,3,1,{"Thelma","There's a sprinkler running on the Fallas Lake road, one of them that walks along the hose","June","Running water","Thelma","Going back and forth on a lawn that's burnt brown to the dirt - nothing left to water, it's just wetting down dust","Thelma","We ain't had pressure on that side since the tenth - my taps spit air and quit","June","So where's the water coming from?","Thelma","Well, that's it, I don't know and I stood in a stranger's driveway a long time not knowing","Thelma","It's got a good head on it too - good pressure, hits the porch rail on the far swing","Thelma","Anyway - y'all got any word on the water down this end, or is it just the sprinkler?"}},
{"r8_hor_yellow_shirt_fields","caller_story_horror",11,130,22,4,1,{"Zella","I'd say four times - five, I'd say five now that I count the first one","June","Five what?","Zella","Same fella standing in a field, yellow shirt, one of them work shirts with the pocket - dead, I mean, he's one of them","Zella","Different fields - Tanner Road, then the bottoms by the creek, then the corn up behind the school","June","There's more than one yellow shirt in this county, Zella","Zella","There is, and I ain't saying it's the same fella, I'm saying it's the same shirt and the same way of standing","Zella","Standing facing the road with his arms down, they don't stand still when a truck goes by - you know that","Zella","Get the Bible. I'll swear to the shirt, June, right now"}},
{"r8_hor_horn_two_long","caller_story_horror",11,130,0,4,1,{"Woodrow","Car horn out on the Irvington road every night about eleven - two long and a short","June","Same pattern?","Woodrow","Two long, one short, that's how my daddy called us in from the field - everybody's daddy had one","Woodrow","So the first night I got up out of bed - second night I got up, third night I put my boots on and my wife stood in the door and wouldn't move","June","She wouldn't let you go","Woodrow","She said Woodrow, whose horn is that, and I didn't have an answer, 'cause my daddy's been gone since eighty-four","June","Somebody could be signaling for help","Woodrow","They could, and if it's a man, then I'm a coward and I'll wear that - it's the fourth night now and it's still two long and a short"}},
{"r8_hor_rooster_at_midnight","caller_story_horror",11,140,0,4,1,{"Loyd","Rooster crows at midnight - every night, one time, then nothing","June","Roosters do crow at odd hours","Loyd","They do, a light'll set one off, a fox'll set one off - I've kept chickens forty years, I know all that","Loyd","Once, though? Roosters don't crow once, they go and go and get the neighbors' going","June","Once and done","Loyd","On the stroke of it, and we ain't got a rooster - we lost the whole flock the second week, something got in the house and took every bird","June","Took them","Loyd","Feathers and no birds, not one carcass in that lot, and something that kills chickens leaves a mess, you know that","Loyd","So I lay there at midnight waiting on a bird I ain't got - that's the shape of my nights now"}},
{"r8_hor_fixed_his_face","caller_story_horror",11,140,23,5,1,{"Nadine","I told a man my brother died, you tell people, it comes up","June","It does","Nadine","He smiled","June","People do strange things when they don't know what to say","Nadine","They do, I've had folks laugh, I've had a woman ask me for a cigarette right in the middle of it, and I didn't hold it against her","Nadine","This was different, he smiled and then he fixed it, I watched him fix his face","Nadine","Pulled it down, piece at a time, like a man setting a table - and then he said the right thing, he said I'm sorry for your loss","June","Where is he now?","Nadine","Eating supper with eleven people I care about, and I got no proof of one single thing, so I called a radio instead"}},
{"r8_hor_cold_handshake","caller_story_horror",11,135,0,4,1,{"Leland","Shook a man's hand at the church Tuesday, ninety-four degrees in the shade, no breeze, everybody wringing wet","June","I remember Tuesday","Leland","His hand was cold - not cool, cold, like he'd had it in a creek","June","Some folks run cold","Leland","My mother did, coldest hands in Knox County, I've heard that my whole life and I'd have said the same thing if you'd said it to me","Leland","Here's my trouble, he shook eleven hands and every one of them looked at their own hand after","June","All of them","Leland","Every one, nobody said a word about it - eleven grown people looked at their hand and put it in their pocket","Leland","And he preached, he preached good, too, that's the part I can't get around"}},
{"r8_hor_list_crossed_off","caller_story_horror",11,140,0,4,1,{"Nell","I left a list on a nail at the crossroads - salt, matches, a needle, aspirin if anybody's got it","June","Asking for a trade","Nell","That's the idea of it, and it's worked twice, fella left me matches in June and I left him tomatoes","Nell","This time the list come back with everything crossed off","June","Crossed off, but nothing left for you","Nell","Nothing there - Nail's bare except the paper, every line struck through with one stroke, top to bottom, like a man keeping books","June","So somebody read it","Nell","Somebody read it and marked it done, and I keep asking myself done where, and I ain't got a good place to put that question","Nell","I quit the nail, I'll do my trading face to face from here on, I don't care how much walking it is"}},
{"r8_hor_pond_went_quiet","caller_story_horror",11,140,22,4,1,{"Almon","I've lived on this pond since I was four years old - sixty-one years","June","Go on","Almon","Bullfrogs on it every summer night of my life, you get used to it, you don't hear it - then you sleep somewhere else and you can't sleep","Almon","It's quit","June","All at once?","Almon","One evening to the next, and it ain't the water, the water's fine, there's turtles on the log and minners in the shallows","Almon","Frogs are in there, I put a light on 'em, there's eyes all over that bank - whole pond full of frogs sitting there not saying a word","June","Sitting there","Almon","Sixty-one years, I got no place to put this, June, that's why I'm calling a radio station about frogs"}},
{"r8_hor_cattle_gate_open","caller_story_horror",11,140,23,5,1,{"Orville","Thirty head in the far corner of a field off the Rosewood road - bunched up tight, heads out, like they do","June","Something after them?","Orville","That's what a bunch means, dog, coyote, something, you see that, you go look","Orville","Gate's standing wide open, whole other end of the field, open to the road","June","They could walk out","Orville","They could walk out, there's green grass in the ditch, there's water in the ditch - they ain't walking out","June","How long have they been in that corner?","Orville","Three days that I know of, they've eat that corner down to dirt and they're standing in it","Orville","I shut the gate - don't ask me why I shut it, felt like the only useful thing I've done all week"}},
{"r8_hor_every_dog_at_once","caller_story_horror",11,135,23,5,2,{"Bonnie","Every dog in Riverside went off at once Thursday night","June","All at once?","Bonnie","Same second, I was on the porch and it come up out of the whole town like somebody threw a switch","Bonnie","That ain't how dogs work, one starts it and the rest catch on, there's always a first dog","June","There wasn't one","Bonnie","There wasn't a first dog, and it went about two minutes and then they all quit at once too, and that's the part","June","Quit together","Bonnie","Dead quiet, dogs don't quit together, they trail off, there's always one fool still going","Bonnie","And there's twelve, fifteen dogs in this town and not one of 'em would come out from under a porch Friday - not for food","Bonnie","That's all I know, I'd just like to hear somebody in West Point say theirs did it too"}},
{"r8_sad_borrowed_mower","caller_story_sad",11,140,17,22,1,{"Marty","Go ahead, sir","Leland","I've got a man's mower in my shed - push mower, self propelled, good one","Marty","Borrowed?","Leland","June, I borrowed it in June, mine wouldn't start, and he said keep it till you get yours going - neighbors do that","Marty","Sure they do","Leland","I pushed it over there Wednesday, whole quarter mile down the road, pushing a mower, felt like a fool the whole way","Marty","Was anybody home?","Leland","No, door's open, been open a while, I put it back in his shed and I hung the gas can on the nail where he keeps it","Leland","Then I cut his front yard, not the back, I run out of gas - front's done though, it looks right from the road","Marty","That was a good thing to do, Leland","Leland","It was something to do, there's a difference and I'm too tired to argue it - his name's Delbert Ray, if anybody sees him"}},
{"r9_so_d11_before_the_coffee","sign_on",11,26,5,8,1,{"Marty","Morning, ninety-nine point six, March Ridge, it's {time} and it's already eighty-one degrees on the grain bin thermometer","Marty","Three of you keyed up on nineteen before I got the coffee water on - I heard all three of you and I answered none of you, and I'm sorry about that","Marty","So - Bess out on Tanner Road, yes, I got it - Wade, no, and I'll say no again tonight, and whoever that was at four this morning who said hello twice, hello","Dee","He drank the coffee before he answered anybody, I watched it happen from the doorway","Marty","I did - count your people - let's go"}},
{"exp_brothers_fence","caller_story_sad",12,3650,0,23,1,{"Ralph","My brother and I didn't speak for eleven years","June","You don't have to name him","Ralph","We argued over where a fence ought to go","June","Eleven years is a long argument","Ralph","I know the measurements of that fence better than I know his children","Ralph","That's what I wanted to say, not a request - just that","June","Thank you for trusting us with it","Ralph","If he's listening, he can have the damn strip of grass"}},
{"king_radio_favorite_noise","caller_story_sad",12,3650,0,23,1,{"Frank","You asked what we missed. I've got a ridiculous one","June","Go on","Frank","My neighbor dragging his garbage cans back up the drive","June","Why that?","Frank","It meant Tuesday. I never had to think about it","June","Did you like the neighbor?","Frank","Not particularly. I'd like another chance at that","June","I hope you get one"}},
{"king_radio_button_tin","caller_story_sad",12,3650,0,23,1,{"Ada","My mother kept spare buttons in a biscuit tin","June","Mine kept sewing things in one","Ada","Always disappointing when you were little","June","You checked anyway","Ada","Every time. She must've thought I was slow","June","Maybe she liked watching you try","Ada","She did laugh a lot. I'd forgotten that part","June","I'm glad you remembered"}},
{"r2_d12_marty_times_colonel","military",12,16,17,22,1,{"Marty","Warden-6 has ordered radio silence four times this week, each time, he explained why at some length, I timed them - the longest ran two minutes and ten seconds","Marty","I don't say it to make fun of the man - I believe he's trying to hold up a fence with his voice","Marty","But if the Army is listening, and I know you are, silence would go a lot further if it came with fewer words","Dee","Marty, you're lecturing a colonel about talking too much, on the radio - that you've been on for four hours tonight","Marty","Noted, here's the Army traffic, and I'll keep my remarks to ten seconds - starting, now"}},
{"r2_d14_striker12_takes_dispatch","military",12,20,7,19,1,{"Striker-12","Knox dispatch, Striker-12, morning check-in, over","Striker-12","Dispatch, Striker-12 - you there, ma'am, over?","Caller - Lorraine","Army? This is Lorraine on Walnut Street in West Point - the dispatcher lady isn't answering - is anybody answering?","Striker-12","Ma'am, this is Striker-12 - I'm, yes - I'm answering - go ahead","Caller - Lorraine","There's black smoke coming off the hardware store on Elm - is there a fire truck?","Striker-12","No, ma'am, there's no fire truck - stay upwind, carry water, and don't go look at it","Caller - Lorraine","Okay, thank you, Army - what's your name, so I know who to ask for?","Striker-12","Just ask for Striker-12, ma'am, I'll be on this channel - I'm not going anywhere else"}},
{"r3_so_d12_tail_counts","sign_on",12,20,5,8,1,{"Marty","Good morning, ninety-nine point six, it's {weekday}, and it's {time}","Marty","Before I start, count your people - I'll wait","Marty","Here, it's me, Dee asleep on a pallet of sweet feed, and Dolly - three - Dolly didn't answer, but I saw the tail move, and that counts","Marty","If your count came up short this morning, I'm sorry - you don't have to tell anybody, you can just listen a while","Marty","Scanner first, the state police channel was dead air all night, the sheriff's channel had one voice around two in the morning, reading off license plate numbers to nobody"}},
{"r3_host_d12_green_ledger","host",12,25,18,23,1,{"Marty","I've been going through the store books to see what we've got left - Nancy kept the ledger, green ledger, one column for feed, one for hardware, one for Marty's nonsense","Marty","The Marty's nonsense column is mostly fishing lures I ordered for the store and then kept","Marty","The last thing in her hand is Thursday, July the eighth - 'Ferrell, fence charger, call.' And next to it she drew a little face with its mouth straight across - that's the face she made at me","Marty","I never did call Ferrell, I don't know what I'd tell him now if I could","Dee","Tell him Nancy's been after you about it","Marty","Yeah, I'll do that"}},
{"r3_ins_d12_ticks_chiggers","instruction",12,30,5,12,1,{"Dee","It's summer in Kentucky, which means you're all being eaten alive, just not by the things you're worried about","Dee","Ticks - check every night, behind the knees, in the hair, all along the waistband - pull them with tweezers, close to the skin, straight out","Dee","Chiggers - you'll know - don't scratch till you bleed, because an open sore in this heat gets infected, and then you're calling me","Dee","If you get a bullseye rash after a tick, or fever and aches a week later, tell somebody - keep track of the day you pulled it - write it on the wall if you have to","Dee","Mosquitoes, dump every puddle you don't need - old tires, flowerpots, buckets you're not drinking out of - cover the ones you are"}},
{"r3_mb_d12_almanac","music_bridge",12,30,9,17,1,{"Marty","Something to fill the gap instead of music, the almanac's planting calendar for this week, read by a man who never once followed it","Marty","Cut hay midweek, pull weeds Saturday, and for fishing the book says any day that ends in Y","Marty","Nancy followed it, she'd put her beans in the day it said, and her beans came up better than mine every year - I'd like to tell you I've made my peace with that","Marty","I have not"}},
{"r4_sad_crayon_labels","caller_story_sad",12,30,17,22,1,{"Caller - Nancy","School supply list for second grade came out on the third of July - we went the same day, she wanted to be first","Caller - Nancy","Twenty-four crayons, safety scissors, two glue sticks, a box of tissues for the class, and a folder with a horse on it","Caller - Nancy","We have one of those label makers that punches letters into tape - she wanted her name on every single crayon","Caller - Nancy","Twenty-four little labels - a-M-B-E-R, it took us all evening - my thumb was sore from clicking the wheel","Dee","That's a lot of crayons to label","Caller - Nancy","The box is on her dresser, the scissors are still in the plastic, I was going to make her wait till school to open them","Caller - Nancy","School was going to start August the eighteenth","Marty","(Marty is silent)","Caller - Nancy","I just didn't want those labels to be for nothing - so now some more people know her name was on them"}},
{"r4_sad_canning_card_hoyt","caller_story_sad",12,30,14,21,1,{"Caller - Hoyt","My wife picked the whole row of pole beans the day before - they were sitting in two bushel baskets on the porch","Caller - Hoyt","I'd never canned anything in my life, forty-four years married and I never so much as boiled a jar","Caller - Hoyt","Found her recipe box, the card for beans has got her handwriting all over it - grease spots, notes in the margin from different years","Caller - Hoyt","At the bottom, underlined twice, it says, process twenty-five minutes at ten pounds - don't rush it, Hoyt","Dee","She wrote your name on it","Caller - Hoyt","I rushed it one time - in seventy-eight, jar blew and she found beans on the ceiling for a year - she never let it go","Caller - Hoyt","Did fourteen quarts over the camp stove, took all day, I kept reading that line out loud to myself - don't rush it, Hoyt","Caller - Hoyt","All fourteen sealed, you hear the lids pop when they cool, I sat there listening to them pop","Marty","(Marty doesn't say anything, somewhere in the studio, Dee blows her nose and apologizes for it)"}},
{"r5_trade_seed_potatoes_gene","trade",12,26,9,16,1,{"Marty","Trading Post - go ahead, caller","Caller - Gene","Marty, this is Gene, out past Ekron, I've got about thirty pounds of seed potatoes, Kennebecs, and they're sprouting on me in the cellar","Marty","What are you looking for, Gene?","Caller - Gene","Canning lids, as many as I can get, and a pair of work boots, ten and a half - mine have split clean across the sole","Marty","Folks, if you get potatoes in the ground by the first week of August, you'll still see a fall crop - that's worth more than lids, but don't tell Gene","Caller - Gene","I can hear you, Marty","Marty","Where will you meet?","Caller - Gene","The Ekron post office, ten in the morning, tomorrow, I'll be the one sitting on a sack of potatoes","Marty","Ekron post office, ten AM, seed potatoes for canning lids and boots, size ten and a half - thank you, Gene"}},
{"r5_host_percolator_grounds","host",12,60,0,23,1,{"Marty","If you're hearing a gurgle, that's the percolator, and it's fixing to be the best thing that happens in March Ridge today","Dee","Those grounds have been through that pot three times","Marty","Four, tonight's the fourth, they're experienced grounds - they know the way","Dee","That ain't coffee anymore, Marty, it's brown water that remembers coffee","Marty","Some of us like to remember","Dee","Everybody, if you have coffee to trade, trade it to me, not him - he's too far gone to tell the difference"}},
{"r5_joke_opal_fourth_worst","caller_joke",12,200,17,22,1,{"Dee","We've got Opal in Brandenburg - Opal, how are you holding up?","Caller - Opal","Honey, I'm eighty-four, I've lived through the Depression, the flood of thirty-seven, and three husbands","Dee","So how does this rank?","Caller - Opal","Fourth worst","Dee","What's worse than this, Opal?","Caller - Opal","Husband number two","Dee","I'm not going to ask","Caller - Opal","Good, it'd take all night, and you've got other callers"}},
{"r5_obit_dee_clarence_hymns","obituary",12,60,0,5,1,{"Dee","Marty's asleep, so it's me for a while, I want to say a name","Dee","Clarence Mapp, he worked nights with me as an orderly for nine years","Dee","When a patient got scared at three in the morning, Clarence would hum a hymn with the words wrong - on purpose","Dee","They'd get so aggravated correcting him, they'd forget what they were scared of - worked on the old Baptist ladies every single time","Dee","I've got his name tag in my bag, it says 'Clarence - ask me anything.' He added the 'ask me anything' himself with a label maker","Dee","That's all, I just didn't want to be the only one left who knew about the hymns"}},
{"r5_host_dee_whiskey_bite","host",12,120,0,23,1,{"Dee","Somebody called yesterday asking whether whiskey will clean a bite","Dee","No, I'm sorry - it won't, nothing I know of cleans a bite, not whiskey, not bleach, not cutting it out","Marty","Dee","Dee","No, Marty, they asked me straight, and I won't lie on this station so the hour goes down easier","Dee","If you're bitten, you've got a little time, spend it with your people - say what needs saying, then do right by them","Marty","We're going to leave the air quiet for a minute"}},
{"r8_hor_shovel_put_back","caller_story_horror",12,150,23,4,2,{"Hoyt","Fresh grave in the side yard of a place off Tanner Road - dug and filled, mounded up proper","June","No marker?","Hoyt","Nothing, no cross, no stone, not a stick with a name on it - and there's no house left standing on that lot, it burned in the spring","Hoyt","So I go in the shed, 'cause I want a shovel - Shovel's in there, hung on the nails","Hoyt","Blade's clean, somebody washed it and hung it back up","June","Somebody buried a person and put the shovel away","Hoyt","Put it away, that's the thing I can't set down - that's a man who's coming back","Hoyt","I left the shovel where it was at, ain't much for taking a thing off a man like that"}},
{"r8_hor_same_mower_three_times","caller_story_horror",12,140,21,3,1,{"Geneva","I want to ask you something and I want you to not make a joke out of it","June","I won't","Geneva","We run the straight stretch out past Wickham's feed store three times Tuesday - hauling water","Geneva","Same turned over riding mower on the shoulder every time - green one, both back wheels off it","June","Three trips, same mower","Geneva","Every trip on the way out, never once on the way back - and we never turned around, we run a loop","Geneva","That road's straight as a rifle, we wasn't lost, you can see a mile of it","June","I don't have an answer for you, I'm not going to invent one","Geneva","Good, everybody else in this house has got one, and I've quit listening to 'em"}},
{"r8_hor_three_cans_on_the_step","caller_story_horror",12,150,0,4,1,{"Ossie","Three cans on my back step Friday morning, green beans, green beans, corn","June","Somebody left you food","Ossie","Kind of somebody, right? That's what my sister said, somebody's being good to you, Ossie","Ossie","Next Friday, three cans, green beans, green beans, corn - same three","Ossie","Third Friday, same three, and this time set up in a little stack, biggest on the bottom","June","Have you eaten them?","Ossie","I got nine cans in the cabinet I ain't touched - I can't, I keep thinking somebody's counting how many's left","June","You don't have to eat a thing you don't want to eat","Ossie","I know, I'd just like one Friday where there's nothing on the step"}},
{"r8_hor_two_piano_notes","caller_story_horror",12,150,23,4,1,{"Velma","We hauled my mother's piano out in June, sold it to a man in Brandenburg for forty dollars and a set of tires","June","So it's gone out of the house","Velma","Gone, there's a square on the floor where the finish is different and four dents in the carpet - that's all that's left of it","Velma","I hear two notes out of that room - two, the same two, low ones, together","June","Have you been in and looked?","Velma","Middle of the day, with my brother - empty room, dents in the carpet","Velma","My mother played in that room fifty-one years, she'd sit down and hit two notes to see if it was in tune before she'd start","June","Two notes","Velma","Same two, and she's buried in the churchyard at March Ridge and I ain't going to say the rest of it out loud"}},
{"r8_hor_practicing_my_name","caller_story_horror",12,150,0,4,2,{"Wanda","A woman come up the drive Sunday, asked for water and I give her water, I'd do that again","June","Did she say who she was?","Wanda","Said her name but I couldn't hold on to it - she got mine right off, though, I told her Wanda and then she used it","Wanda","Every sentence - sure, Wanda, that's right, Wanda - oh I know it, Wanda","June","Some folks talk like that","Wanda","They do, my aunt does it, drives you up a wall - this wasn't that","Wanda","It was like she was getting used to saying it - like a girl practicing a spelling word","June","Did she leave?","Wanda","She left, and I'll tell you, I ain't told a stranger my name since, and I was raised better than that"}},
{"r8_hor_copying_his_name","caller_story_horror",12,145,22,4,1,{"Roberta","We write folks down at the gate, name, where from, where to - no rule about it, just so we know who come through","June","Reasonable","Roberta","Fella took the pencil and wrote three letters and stopped - sat there with the pencil down on the paper","June","Couldn't spell it?","Roberta","Plenty of folks can't write, and I never make a thing of it, I just write it for 'em - that ain't what this was","Roberta","He was looking at the inside of his own wrist - then he'd write a letter, then look again","June","Was something written on his wrist?","Roberta","I didn't ask - God help me, I did not ask, and I've thought about that every night since","Roberta","He got it all wrote out, nice hand, too, once he got going - then he thanked me and walked off toward Rosewood"}},
{"r8_hor_road_names_wrong_order","caller_story_horror",12,150,0,4,1,{"Virgil","Man said he was from here, said Riverside, born and raised, and he had it right, the accent and everything","June","So a neighbor","Virgil","I've lived here since fifty-eight, I know the families, and I didn't know his - which don't mean a thing by itself","Virgil","He was telling how he come up, named the roads - got every road right","June","Then what's wrong?","Virgil","Wrong order, he had Tanner before the creek crossing, and Tanner's after - then he had the church before the bins","Virgil","Every road in this end of the county, in the wrong order - like a man reading a list somebody handed him","June","Did you correct him?","Virgil","No, I asked him how's his mama and them, which is what you say, and he said she's fine and thanked me for asking","Virgil","I'd have felt better if he'd said he didn't have a mama - that's a thing I never thought I'd hear myself say"}},
{"r8_hor_jug_come_back_washed","caller_story_horror",12,150,23,5,1,{"Geneva","I set a jug of water out at the road for whoever's walking - my mother did that in the Depression and I heard about it my whole life","June","That's a kind thing to keep up","Geneva","It's water, it's the one thing we got plenty of, there's a spring on this place","Geneva","The jug comes back washed","June","Washed","Geneva","Empty and washed and set on the same rock, right side up, with the lid screwed on - every time, eleven times now","June","Somebody's being careful with your jug","Geneva","Washed with soap, June, you can smell it - who's got soap to waste on a stranger's jug, and where are they washing it?","Geneva","I still set it out - don't get me wrong, I just don't go to the road for it no more, I send my grandson at noon"}},
{"r8_hor_no_crickets","caller_story_horror",12,150,1,5,1,{"Faye","I'm going to call about a nothing - it's nothing, it's the biggest nothing I ever sat in","June","Go ahead","Faye","I was on the porch ten minutes before it got to me - ten minutes of something being wrong and me not knowing what","Faye","No crickets","June","None at all","Faye","July, in Kentucky, hot as blue blazes, there ought to be a wall of 'em, you can't hardly talk over 'em in a normal year","Faye","No katydids neither, no tree frogs - it's like somebody turned a dial","June","How long has it been like that?","Faye","Three nights, and I'll tell you, I have got the radio on loud now, and it ain't for the company - it's so I don't have to hear that"}},
{"r8_hor_dog_growls_at_chair","caller_story_horror",12,150,0,4,1,{"Velma","Our dog growls at a chair","June","One particular chair?","Velma","Recliner in the front room, my daddy's chair, and he's been dead four years, so we're all used to it sitting there empty","Velma","Low growl, down in the chest, the kind where the lip don't even come up","June","When does she do it?","Velma","Evening, mostly, seven, eight o'clock - about when he'd have been in it","June","Has anything been moved?","Velma","That's a good question and I wish it was no - the footrest is out, I put it in every morning and by dark it's out again","June","Somebody in the house could be doing that","Velma","There's just me and my girl and the dog, she's six and she can't work that lever, I've watched her try, she ain't heavy enough","Velma","So I've quit putting it in - it's out, it's a footrest, whoever wants it out can have it out"}},
{"r8_hor_heard_a_whole_town","caller_story_horror",12,150,1,5,1,{"Ewell","Stood up on the ridge above the Kelso place Sunday evening - high point, you can see three counties in the daytime","June","Go on","Ewell","I heard a town","June","Voices?","Ewell","Not a word of it, you couldn't pick out one thing, it was the shape of a town making noise - you know it when you hear it","Ewell","Like standing outside the fair, all of it at once and none of it anything","June","How far off?","Ewell","Ten mile, there's nothing between here and there but timber and bottom ground, and there ain't a town in that direction","Ewell","There's a town's worth of something down there, and it was still going when I come down off that ridge in the dark, which I do not recommend"}},
{"r8_sad_empty_bus_route","caller_story_sad",12,150,5,9,1,{"Marty","Morning - Marty at the feed store - go ahead, you're on","Wanda","I drive a school bus, route nine, out the Ekron road and back - twenty-two years","Marty","Twenty-two years on the same road","Wanda","I still run it, seven ten out of the lot, there's diesel in the tank and nobody's using it for anything else","Marty","With no children on it","Wanda","I do the stops - all forty-one, I put the arm out and everything, which is the part my son says I ought to quit doing","Wanda","There's a boy at the fourth stop always come out of the house running - every morning of his life, running, with his shoe untied","Marty","Wanda","Wanda","I sit there about a minute at that one, then I shut the door and go on to the fifth - anyway","Wanda","Y'all got any word on whether there's fuel at the county garage? That's a real question - I'm down to a quarter tank"}},
{"r8_sad_her_voice_on_nineteen","caller_story_sad",12,160,22,4,2,{"June","Go ahead","Lonnie","I have to sit down to tell this and I'm already sat down, so that don't help","June","Take it however","Lonnie","My sister was in Valley Station, nobody's heard a thing out of Valley Station since the tenth and you know that, you've said it on here","June","I have","Lonnie","Wednesday night her voice come over nineteen","June","Her","Lonnie","Her, asking for anybody, saying her own name and asking for anybody at all","Lonnie","I got down on the floor of the truck, not on the seat - on the floor with the mic in my lap, and I sat there a while before I could key it","June","Did you get her?","Lonnie","I got her - eleven minutes, she's at a school with nineteen people and a well - she said the well's good","Lonnie","Her name's Sudie Pruitt and she's alive as of Wednesday night - that's what I come on here to put out in the air where it can't be took back"}},
{"r9_sf_d12_check_on_list","sign_off",12,30,21,23,1,{"Marty","That's the day, before I go, the check-on list, which is a thing we started three days ago and I already don't care for the length of it","Marty","If you're close to one of these, walk over tomorrow in the daylight - not tonight, not by yourself - and holler from the road before you come up the drive","Marty","The old Kelso place on Echo Creek Road, the white house with the swing set on Halbert Street - and Miz Almeda Sipes, behind the Ekron post office, who has got about nine cats and no radio","Dee","Holler from the road, people are shooting at noises now, and a neighbor walking up a driveway is a noise","Marty","Count your people, ninety-nine point six, good night"}},
{"king_radio_church_key","caller_story_sad",13,3650,0,23,1,{"Edna","I used to let everybody into the church for meetings","June","Did you have the key?","Edna","Yes. Always complained about people not putting the chairs back","June","Were there a lot of meetings?","Edna","Choir, scouts, people trying to stop drinking. Everybody wanted a different night","June","Sounds like a lot of people knew you","Edna","I hope they knew they were welcome, too","June","You kept opening the door. That counts for something"}},
{"r2_d13_warning_on_cassette","military",13,18,7,20,1,{"Lockbox-1-6","Warden Tac, Lockbox-1-6, TCP 1, five personnel present at the bridge - Lockbox-6 is no longer with us, over","Warden Tac","Roger, five - are you able to hold, over?","Lockbox-1-6","We can hold the barrier, we can't run the loudspeaker and man the rifles both - request guidance, over","Warden Tac","Keep the speaker on the approved text at the fifth pole - record it if you have to, over","Lockbox-1-6","Roger, private Dunn has a tape recorder - we'll put the warning on a cassette and loop it, over","Warden Tac","Approved - use Lockbox-6's words exactly - don't change a word, over","Lockbox-1-6","Not one word - Dunn's recording now, he says that tape used to have his sister's high school graduation on it, over","Warden Tac","Understood - Warden Tac, out"}},
{"r3_sf_d13_fill_jugs_tonight","sign_off",13,30,22,1,1,{"Marty","Good night from March Ridge - count your people, check your locks, and fill the water jugs tonight instead of in the morning","Marty","You'll be more tired in the morning than you are right now - everybody is, lately, do yourself the favor while you can still stand up","Marty","Dee's on nineteen till two for anybody who needs a voice - this is Marty Colburn - good night"}},
{"r3_wx_d13_fog_from_the_door","weather",13,22,5,8,1,{"Dee","Weather, from the night shift, because Marty's still asleep and I'm the one standing in the door","Dee","There's fog laying in all the low places, heavy, I can't see the road from the lot - it'll burn off by nine, maybe ten","Dee","Here's the thing about fog, it carries sound funny - something can sound like it's way off down the road and be right there in the ditch","Dee","So stay put till it lifts, whatever you were going out for will still be there at ten","Dee","After the fog, hot - Marty's knee reported in last night before bed, and I'm quoting the knee here - 'hot'"}},
{"r8_hor_polaroid_stack_table","caller_story_horror",13,160,23,4,1,{"Burl","You still there? I lost you a second","June","I'm here","Burl","Little house on Halbert, card table in the front room with a stack of them instant pictures on it, squared up like a deck","Burl","Forty, fifty of 'em, and every one is a picture of a room - no people, kitchens, hallways, a bathroom","June","Rooms in that house?","Burl","That's what I figured, but I went through the whole house and I didn't match a one of 'em","Burl","They're other people's rooms - whole stack, somebody's been going in houses and taking a picture of the front room and going on","June","I'd put that stack down and leave it where it was","Burl","I did, then I set outside in the truck and thought about my own front room for a while"}},
{"r8_hor_gate_rehung","caller_story_horror",13,160,21,3,2,{"Virgil","We keep a gate unhooked on the lane so we can get the truck through quick - been that way since the tenth","June","Somebody keeps closing it?","Virgil","Hooked, not just shut, hooked, chain through and the chain laid over the same way I'd lay it","Virgil","I unhook it, and inside a day it's back hooked - eight times now, I quit counting after eight","June","Have you sat on it?","Virgil","Two nights in the bed of the truck with a light - nothing came, third morning it was hooked and I was fifty foot away asleep","June","Fifty foot","Virgil","My boy wants to leave it hooked and go around - and I think that's what a sensible man does, so we're going to do that"}},
{"r8_hor_school_bell_three_fifteen","caller_story_horror",13,160,21,3,1,{"Nell","I taught at the elementary in Riverside nineteen years, I know that bell like my own kitchen","June","Go ahead, ma'am","Nell","It rang Thursday at three fifteen, that's the last bell - that's the one that let them out","Nell","There's no power to that building, the lines come off the pole on the school side and the pole's laying in the ditch","June","Somebody with a generator?","Nell","You'd have to know where the panel is and which breaker - and you'd have to want to ring the last bell","June","How long did it go?","Nell","The full length, it's a long bell, it goes about nine seconds - I stood in my kitchen and waited it out","Nell","Then it got quiet and I put the kettle on for something to do with my hands"}},
{"r8_hor_woman_laughing_far_off","caller_story_horror",13,165,1,5,1,{"Arvel","I got no business calling but my brother in law said call, so","June","He was right - go ahead","Arvel","A woman laughing out in the timber - way off, half a mile, maybe more","June","Once, or more than once?","Arvel","Once a night, a real laugh, too, not a scream, I know what a scream sounds like out here now - a good laugh, like somebody said something","Arvel","There ain't but one house out that way and I helped bury the people in it","June","I'm sorry","Arvel","Don't be, I called 'cause I heard laughing, and a laugh takes two, and I was alone out there at two in the morning","Arvel","So there's two, that's all I wanted to put out there - there's two of something out there and one of 'em's funny"}},
{"r8_hor_asked_after_my_dog","caller_story_horror",13,160,0,4,1,{"Coy","Man at the trade at Wickham's feed store - friendly fella, traded me a jug of bleach for shells","June","Fair trade","Coy","Better than fair, and that ought to have told me something right there","Coy","He asked after my dog - by name, he said how's Sadie getting on","June","Maybe somebody there knew you","Coy","Nine people at that trade and I know every one of 'em, and none of 'em was near enough to hear a word we said","Coy","And I hadn't said one word about having a dog - not to him, not to nobody that day","June","What did you tell him?","Coy","I said she's fine, then I got in the truck - she's dead, is the thing - Sadie's been dead since the twelfth"}},
{"r8_hor_breathing_with_me","caller_story_horror",13,155,1,5,1,{"Pauline","Woman shared our lean-to two nights in the rain, never got her name, she never offered one","June","That happens","Pauline","It does, and I don't hold it against nobody now - half the county's quit giving names out","Pauline","She breathed when I breathed","June","In time with you","Pauline","In - out - with me, I laid there and held mine to see, and she held hers","June","How long did that go on?","Pauline","Till I made myself breathe regular again, 'cause I got frightened of what I was doing - testing her like that","Pauline","She was gone in the morning and she took nothing - not a thing of ours moved, that's the part that sits on me worst"}},
{"r8_hor_childs_printing_answer","caller_story_horror",13,165,1,5,1,{"Ferrell","My boy's fourteen, he run off on the ninth, and the why of it stays in the family","June","You don't have to","Ferrell","I been leaving notes for him, his grandmother's porch, the school, the dugout at the ball field - places he'd go","Ferrell","Somebody answered one","June","Him?","Ferrell","No, that's why I'm calling - it's printed, big letters, all capitals, the way a little kid prints, six or seven years old","Ferrell","It says he's fine - three words, he is fine","June","That could be a child passing along something true","Ferrell","It could be, and I want it to be so bad I can't hardly breathe - but it's on the back of my own note, and my note was in an envelope, and the envelope's still shut","Ferrell","Anyway, if anybody's seen a tall boy in a blue ball cap, that's Wendell Six, and I'd stand you a tank of gas"}},
{"r8_hor_nothing_rising_at_dusk","caller_story_horror",13,160,21,3,1,{"Chester","I fish the creek below the Carver bridge, have since I was a boy, and it's how we're eating, mostly","June","Fishing's feeding a lot of people right now","Chester","It was, last week they quit rising","June","Quit biting?","Chester","No, ma'am, I mean rising, at dusk a creek comes alive on top - bugs on the water, fish taking 'em, rings all over it","Chester","Flat, flat as a table, an hour after sundown, three evenings running","Chester","The fish are in there, I've took four out of the hole on a worm on the bottom - they ain't dead, they ain't gone","June","They just won't come up","Chester","They won't come up, and I've fished forty years and I've never once wondered what a fish knows"}},
{"r8_hor_cat_at_the_stairs","caller_story_horror",13,160,0,4,2,{"Lurlene","I nailed a room shut, upstairs, back bedroom, I'm not going to say what for and don't ask me","June","I won't ask","Lurlene","Six boards across the door and the frame, and two across the bottom of the stairs, and I done it myself with a hammer","Lurlene","My cat sits at the bottom of them stairs and looks up","June","Just sits there","Lurlene","Hours, she'll come get her supper and go right back and sit - tail flat out behind her - ears up","Lurlene","She's fourteen years old, she has never in her life gone up them stairs, she can't make the turn no more","June","Is there any noise from up there?","Lurlene","Not one sound, that's the only reason I can stand it - and the cat sits there anyhow, and she's not wrong about things, she never has been"}},
{"r8_hor_dust_no_truck","caller_story_horror",13,165,21,3,1,{"Nadine","Dust cloud coming up our gravel road, which means a vehicle - it don't mean anything else","June","Somebody driving in","Nadine","That's what we thought, we took our places, which is a thing we've had to learn, and we waited on it","Nadine","It come the whole half mile and went on past the lane and up toward the church, and there wasn't nothing in it","June","No vehicle","Nadine","Nobody on the road at all, and not a breath of wind, it was dead still","June","Just the dust","Nadine","Rolling along about the speed of a truck and settling behind itself - four of us stood there and watched it go by","Nadine","My husband says heat - dust devil, and I said honey, a dust devil don't stay in the wheel tracks, and he ain't spoke of it since"}},
{"r8_sad_two_fair_tickets","caller_story_sad",13,160,21,3,1,{"Glenda","There's an envelope on my refrigerator with two tickets in it","June","Tickets to what?","Glenda","County fair, advance sale, you buy 'em at the bank in June and you save a dollar apiece","Glenda","Me and my husband went every year since we was seventeen - we'd go Thursday, 'cause Thursday's the tractor pull and Friday's too crowded","June","Thursday","Glenda","They're still on the refrigerator under a magnet shaped like a strawberry - dollar off apiece, two of 'em","June","Is he with you?","Glenda","No, and I'm not going to tell that part, it's not what I called about","Glenda","There ain't going to be a fair, I know there ain't - I've quit taking 'em down to look at 'em, that's progress I guess","Glenda","Anyway, if anybody's got a working icebox and wants two fair tickets for a magnet, I'm on the Irvington road"}},
{"r8_sad_does_graduation_count","caller_story_sad",13,170,20,2,1,{"Marty","Go ahead, you're on","Faye","I'm seventeen, I was a senior this year coming up, at the county high school","Marty","All right","Faye","I had my credits, I did summer school in June for the one I was short on and I passed it, I got the slip","Marty","So you finished","Faye","That's what I'm asking - does it count? There's nobody at that school, there's no office, nobody's going to mail anything to anybody","Marty","Who signed your slip?","Faye","Mrs. Six - algebra, she wrote a C plus on it and put her initials and said you got it, don't ever take my class again","Marty","Then it counts, I'll say it on the radio and everybody listening heard me say it - you graduated, and Mrs. Six signed off on it","Faye","Okay","Faye","I've got the slip in my back pocket, I've had it in my back pocket since the eighth - anyway, that's all I wanted to ask"}},
{"r9_host_d13_soldering_lesson","host",13,45,0,23,1,{"Marty","Lloyd's rig picked up a hum yesterday, I'm going to describe the hum, and then a man is going to tell me what to do about it, live, because he can't get over here","Marty","The hum is low and steady and it gets worse when the fan kicks on - Estel, can you hear it through the radio?","Caller - Estel","I hear it, that's a bad ground or a cold joint - do you have a soldering iron, Marty? An iron, not a torch","Marty","I have an iron, I have used it twice in my life and I did it wrong both times","Caller - Estel","Then you'll do fine, heat the joint, not the solder - count three on the joint, feed it, pull the iron off, and don't blow on it","Marty","Don't blow on it","Caller - Estel","Everybody blows on it, that's why everybody's joint looks like a raisin - leave it alone and it'll come out shiny","Marty","Folks, we're off the air a minute - Estel Combs of West Point is teaching a fifty-six year old man to solder over the radio"}},
{"exp_piano_scale","caller_story_sad",14,3650,0,23,1,{"Hugh","I complained about the girl next door practicing piano","June","Did she play at strange hours?","Hugh","No, perfectly reasonable hours, I was just a miserable neighbor","June","What did she practice?","Hugh","Scales, got stuck at the same place every afternoon","Hugh","I can hear the mistake better than I remember any proper music","June","Did you ever speak to her?","Hugh","Only to complain, that's not a very good thing to have left"}},
{"exp_wedding_chair","caller_story_sad",14,3650,0,23,1,{"Frances","We rented folding chairs for my wedding, one never got returned","June","How long had you had it?","Frances","Thirty-two years, it became the chair everybody argued over on the porch","June","Was it particularly comfortable?","Frances","No, it was terrible - Pinched your fingers if you folded it wrong","Frances","But we all knew exactly how to sit in it","June","Strange how a borrowed thing becomes part of a family","Frances","I hope the rental company isn't still counting"}},
{"exp_dancing_lessons","caller_joke",14,3650,0,23,1,{"Neal","Paid for dancing lessons before my cousin's wedding","June","Did the lessons help you?","Neal","Made me fully aware of every mistake","June","Awareness is the first step, they say","Neal","First step was my problem, second one belonged on somebody else's shoe","June","Did your partner forgive you?","Neal","She said she'd rather hear my excuse than watch another demonstration","June","I think we'll follow her example on the radio"}},
{"exp_fishing_hat","caller_joke",14,3650,0,23,1,{"Del","My fishing hat had more hooks in it than I ever used","June","Decoration or storage?","Del","Mostly advertising, wanted people to think I knew something","June","Did you know something?","Del","Knew not to sit on the hat","June","Hard-earned knowledge?","Del","I decline to discuss my education","June","We'll credit you with a practical qualification"}},
{"exp_fair_ribbon","caller_joke",14,3650,0,23,1,{"Silas","I once won third prize for a squash","June","That's a fine agricultural achievement","Silas","There were three entries, one got dropped carrying it in","June","Yet you held on to third","Silas","The judges admired the broken one's promise","June","Tough competition from the floor","Silas","I ate mine, nobody's eaten a ribbon and enjoyed it","June","We'll accept that as your concession speech"}},
{"exp_casserole_contest","caller_joke",14,3650,0,23,1,{"Vera","Every church supper had one casserole nobody could identify","June","Did anyone ever ask who made it?","Vera","Not directly, we were polite people","June","So how did you investigate?","Vera","Watched who took the dish home","June","Very discreet detective work","Vera","Then that woman would bring the same thing next time - we never learned","June","A mystery renewed by popular avoidance"}},
{"exp_watch_check","military",14,3650,22,5,1,{"Kilo Two","Checking the set, not a contact report","Kilo One","Reading you - how's your alertness?","Kilo Two","Have to work at it now","Kilo One","Don't hide fatigue from me","Kilo Two","I just reported it","Kilo One","Understood - keep the check-ins plain","Kilo Two","No argument there, I'm out of decorative language","Kilo One","You never had much, that's why I asked you"}},
{"exp_insomnia_count","caller_story_sad",14,3650,23,5,1,{"Winnie","I used to count backwards to fall asleep","June","Does it still help at all?","Winnie","I get to a number and remember someone's age","Winnie","Then I've got a whole person to think about","June","You don't have to chase the numbers tonight","Winnie","What are you thinking about over there?","June","Whether the next caller has been waiting for me to finish","Winnie","I'll let them have a turn, thanks for spending a little of the dark with me"}},
{"exp_trucker_dark","caller_story_sad",14,3650,21,5,1,{"Wade","Night driving used to feel like having the whole road to myself","June","Was that something you enjoyed?","Wade","For a while, then I'd look for the next truck's lights","June","Even if you didn't know the driver?","Wade","Didn't need to, somebody else choosing to stay awake was enough","June","I suppose a radio can do a little of that","Wade","That's why I called instead of telling the story to the windshield","June","The windshield probably had fewer interruptions"}},
}
